    deepExplanation: "Step 1 — Build an adjacency list:\n```ts\ntype Graph = readonly (readonly number[])[];\n```\n\nWITHOUT BUILT-IN / CORE:\n```ts\ntype Graph = readonly (readonly number[])[];\n\nfunction bfs(start: number, graph: Graph): number[] {\n  const queue: number[] = [start];\n  const visited = new Array<boolean>(graph.length).fill(false);\n  const order: number[] = [];\n\n  let front = 0;\n  visited[start] = true;\n\n  while (front < queue.length) {\n    const node = queue[front++]!;\n    order.push(node);\n\n    for (const next of graph[node] ?? []) {\n      if (visited[next]) continue;\n\n      visited[next] = true;\n      queue.push(next);\n    }\n  }\n\n  return order;\n}\n```\n\nWITH BUILT-IN:\n```ts\ntype Graph = readonly (readonly number[])[];\n\nfunction bfsUsingSet(start: number, graph: Graph): number[] {\n  const queue = [start];\n  const visited = new Set<number>([start]);\n  const order: number[] = [];\n  let front = 0;\n\n  while (front < queue.length) {\n    const node = queue[front++]!;\n    order.push(node);\n\n    for (const next of graph[node] ?? []) {\n      if (visited.has(next)) continue;\n\n      visited.add(next);\n      queue.push(next);\n    }\n  }\n\n  return order;\n}\n```\n\nStep 2 — Example:\n0 → [1,2]\n1 → [3]\n2 → [4]\nBFS from 0 → [0,1,2,3,4].\n\nStep 3 — Complexity:\nO(V+E) time for an adjacency-list graph and O(V) auxiliary space.\n\nStep 4 — Key rule:\nQueue order gives level-by-level exploration.",
